		}
		if hasResultPayload(r.Result) {
			return nil, fmt.Errorf("REJECT_WITH_SIDE_EFFECT_PAYLOAD")
		}
	} else {
		// rule 0 of the published CommandResponse: only REJECTED may carry error fields.
		if r.ErrorCode != nil || r.Error != nil {
